#!/usr/bin/python
"""Atomically upgrade the catalog database from schema v1 to v2."""

import os
import sqlite3

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DATABASE = os.path.join(BASE, "catalog.db")


def product_columns(connection):
    return connection.execute("PRAGMA table_info(products)").fetchall()


def valid_v2(connection):
    columns = product_columns(connection)
    names = [column[1] for column in columns]
    if names != ["id", "description", "price_cents"]:
        return False
    price = columns[2]
    if price[2].upper() != "INTEGER" or price[3] != 1 or str(price[4]) not in ("0", "'0'", '"0"'):
        return False
    table_sql = connection.execute(
        "SELECT sql FROM sqlite_master WHERE type='table' AND name='products'"
    ).fetchone()
    return table_sql is not None and "CHECK (price_cents >= 0)" in table_sql[0]


def upgrade():
    connection = sqlite3.connect(DATABASE)
    try:
        connection.execute("BEGIN IMMEDIATE")
        versions = connection.execute("SELECT version FROM schema_version").fetchall()

        if versions == [(2,)]:
            if not valid_v2(connection):
                raise RuntimeError("schema_version is 2 but the v2 products schema is invalid")
            connection.commit()
            return

        if versions != [(1,)]:
            raise RuntimeError("expected exactly one schema_version row at version 1")

        columns = product_columns(connection)
        if [column[1] for column in columns] != ["id", "description"]:
            raise RuntimeError("products table does not match the expected v1 schema")

        connection.execute(
            "ALTER TABLE products ADD COLUMN price_cents "
            "INTEGER NOT NULL DEFAULT 0 CHECK (price_cents >= 0)"
        )
        cursor = connection.execute(
            "UPDATE schema_version SET version = 2 WHERE version = 1"
        )
        if cursor.rowcount != 1 or not valid_v2(connection):
            raise RuntimeError("v2 schema validation failed")
        connection.commit()
    except Exception:
        connection.rollback()
        raise
    finally:
        connection.close()


if __name__ == "__main__":
    upgrade()
